{
  "description": "Reaction sticker: one transparent PNG (Crodie emote, logo, CTA banner, badge) pops / slides / stamps in at a corner, side or centre, holds with a little life, then leaves.",
  "kind": "overlay",
  "duration": 1.6,
  "stretchable": true,
  "min_duration": 1.0,
  "orientations": ["landscape", "vertical"],
  "vars": {
    "image":    {"type": "string", "label": "Sticker image: local PNG path (motion.py inlines it), data: URI or http(s) URL. Default is relative to studio/ (run from there); empty = nothing drawn", "default": "motion/templates/sticker_pop/default.png"},
    "position": {"type": "string", "label": "top-right | top-left | bottom-right | bottom-left | center | left | right", "default": "top-right"},
    "style":    {"type": "string", "label": "pop (elastic pop + impact ring + idle bob) | slide (CTA banners, from the nearest side) | stamp (slam + dust, for badges)", "default": "pop"},
    "size":     {"type": "number", "label": "Sticker height as a fraction of frame HEIGHT (landscape) or frame WIDTH (vertical). 0 = auto (0.30 / 0.42; centre 0.40 / 0.55)", "default": 0},
    "tilt":     {"type": "string", "label": "Resting tilt in degrees, or 'auto' (+4 right side, -4 left side, +3 centre)", "default": "auto"},
    "opaque":   {"type": "boolean", "label": "Opaque ink background", "default": false}
  }
}
<div id="sp-anchor" data-layout-allow-overflow>
  <div id="sp-flash" data-layout-allow-overlap data-layout-allow-overflow></div>
  <div id="sp-ring" data-layout-allow-overlap data-layout-allow-overflow></div>
  <div id="sp-dust" data-layout-allow-overflow></div>
  <div id="sp-bob" data-layout-allow-overflow><div id="sp-sticker" data-layout-allow-overflow></div></div>
</div>
/* Sticker pop. Box sizes/positions are set in template.js (logical px). */
#sp-anchor { position: absolute; left: 0; top: 0; }
#sp-bob, #sp-sticker { position: absolute; inset: 0; }
#sp-sticker img {
  display: block; width: 100%; height: 100%; object-fit: contain;
  image-rendering: auto;
  /* the art already has a dark outline: just a soft drop shadow to lift it off the footage */
  filter: drop-shadow(0 3px 0 rgba(0,0,0,0.35)) drop-shadow(0 6px 8px rgba(0,0,0,0.4));
}
#sp-flash, #sp-ring { position: absolute; border-radius: 50%; opacity: 0; }
#sp-flash { background: radial-gradient(circle, #fff 0 45%, rgba(255,255,255,0.75) 60%, rgba(255,255,255,0) 72%); }
#sp-ring { border: 5px solid #fff; box-shadow: 0 0 0 2px rgba(0,0,0,0.18), inset 0 0 0 2px rgba(0,0,0,0.18); }
#sp-dust { position: absolute; inset: 0; }
.sp-px { position: absolute; border: 2px solid #000; box-shadow: inset -2px -2px 0 rgba(0,0,0,0.25); opacity: 0; }
MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h, D = d.duration;
  var clamp = function (a, lo, hi) { return Math.max(lo, Math.min(hi, a)); };
  var rnd = MC.rng(4242);

  // ---- vars
  var POS = ["top-right", "top-left", "bottom-right", "bottom-left", "center", "left", "right"];
  var pos = String(v.position || "top-right").trim().toLowerCase().replace(/[\s_]+/g, "-");
  if (pos === "centre" || pos === "middle") pos = "center";
  if (POS.indexOf(pos) < 0) pos = "top-right";
  var style = String(v.style || "pop").trim().toLowerCase();
