        return (1 + (((b1 & 0x3f) << 8) | b0)) / (1 + (((b3 & 0xf) << 10) | (b2 << 2) | ((b1 & 0xc0) >> 6)));
      }
      return 0;
    }
    if (u8(h, 0) === 0xff && u8(h, 1) === 0xd8) {   // JPEG: walk the markers to the SOF
      var j = bytesOf(b, 262144), i = 2;
      while (i + 9 < j.length) {
        if (u8(j, i) !== 0xff) { i++; continue; }
        var mk = u8(j, i + 1), len = u8(j, i + 2) << 8 | u8(j, i + 3);
        if (mk >= 0xc0 && mk <= 0xcf && mk !== 0xc4 && mk !== 0xc8 && mk !== 0xcc) {
