    if (vb) return +vb[1] / +vb[2];
    var w = /<svg[^>]*\swidth\s*=\s*["']([\d.]+)/i.exec(t), hh = /<svg[^>]*\sheight\s*=\s*["']([\d.]+)/i.exec(t);
    return w && hh ? +w[1] / +hh[1] : 0;
