  aspect = clamp(aspect, 0.2, 6);

  // ---- layout (logical canvas 960x540 / 540x960)
  var vert = d.vertical;
  var safeTop = vert ? H * 0.105 : H * 0.05;          // vertical: clear of the Shorts header (~10%)
  var safeBot = vert ? H * 0.735 : H * 0.95;          // vertical: clear of captions / buttons (~26%)
  var inset = vert ? W * 0.04 : W * 0.04;
  var center = pos === "center";
  var autoSize = vert ? (center ? 0.55 : 0.42) : (center ? 0.40 : 0.30);
  var size = MC.num(v.size, 0);
  size = size > 0 ? clamp(size, 0.05, center ? 0.9 : 0.6) : autoSize;
  var boxH = size * (vert ? W : H);                    // landscape: fraction of height, vertical: fraction of width
  var capW = (vert ? (center ? 0.92 : 0.8) : (center ? 0.7 : 0.45)) * W;   // wide CTA banners: by height, capped by width
  var bandH = safeBot - safeTop;
