  else y = vert ? safeTop + (bandH - dh) / 2 : (H - dh) / 2;   // vertical centre/sides: middle of the safe band

  var anchor = document.getElementById("sp-anchor");
  anchor.style.left = x.toFixed(1) + "px"; anchor.style.top = y.toFixed(1) + "px";
  anchor.style.width = dw.toFixed(1) + "px"; anchor.style.height = dh.toFixed(1) + "px";
  var bob = document.getElementById("sp-bob"), st = document.getElementById("sp-sticker");
  if (src) {
    var img = document.createElement("img");
    img.src = src; img.alt = "";
    img.setAttribute("data-layout-allow-overflow", "");
    st.appendChild(img);
