    var n = Math.max(1, Math.round(hold / 0.42));
    tl.fromTo(bob, { y: 0 }, { y: -amp, duration: hold / n, ease: "sine.inOut", repeat: n - 1, yoyo: true, immediateRender: false }, t0);
    var m = Math.max(1, Math.round(hold / 0.3));
    if (rotAmp) {
      var ks = [];
      for (var i = 0; i < m; i++) ks.push({ rotation: (i % 2 ? -1 : 1) * rotAmp, duration: hold / m, ease: "sine.inOut" });
