      keyframes: [
        { scale: 1.15, duration: 0.15, ease: "power2.out" },
        { scale: 0.95, duration: 0.08, ease: "power1.inOut" },
        { scale: 1, duration: 0.1, ease: "power1.out" }
      ] }, 0);
    tl.to(st, { rotation: tilt, duration: 0.36, ease: "back.out(2.6)" }, 0);
    tl.fromTo(flash, { scale: 0.2, opacity: 0 }, { keyframes: [
