    tl.fromTo(st, { scale: 1.6, rotation: tilt - 10, opacity: 0 }, { scale: 0.92, rotation: tilt, duration: T, ease: "power3.in" }, 0);
    tl.fromTo(st, { opacity: 0 }, { opacity: 1, duration: 0.06, ease: "none", immediateRender: false }, 0.005);
    tl.to(st, { keyframes: [{ scale: 1.05, duration: 0.08, ease: "power2.out" }, { scale: 1, duration: 0.12, ease: "power1.inOut" }] }, T);
