    var dust = document.getElementById("sp-dust");
    var cols = ["#ffffff", "#c9c9c9", "#e9e3d4", "#9e9e9e"];
    for (var k = 0; k < 4; k++) {
      var p = document.createElement("div");
      p.className = "sp-px";
      p.setAttribute("data-layout-allow-overlap", ""); p.setAttribute("data-layout-allow-overflow", "");
