{
  "description": "1.8s result stamp: a big Crodie badge (W / L / GG / HYPE / EZ) slams into the centre with shockwave rings; win = pixel confetti in brand colours, lose = a grey pixel rain cloud and a droop, neutral = sparkles. A Crodie emote pops in beside it reacting.",
  "kind": "overlay",
  "duration": 1.8,
  "orientations": ["landscape", "vertical"],
  "vars": {
    "badge":  {"type": "string", "label": "Badge image (local path, inlined by motion.py): brand/crodie/emotes/badge_w.png | badge_l.png | badge_gg.png | badge_hype.png | badge_ez.png", "default": "brand/crodie/emotes/badge_w.png"},
    "emote":  {"type": "string", "label": "Reacting Crodie emote (local path). Suggested: win fist_pump, lose crying_waterfall / teary_sad, neutral thinking_chin. Empty = none", "default": "brand/crodie/emotes/fist_pump.png"},
    "mood":   {"type": "string", "label": "win (confetti) | lose (grey rain + droop) | neutral (sparkles)", "default": "win"},
    "opaque": {"type": "boolean", "label": "Opaque ink background", "default": false}
  }
}

input.content:
#cv-all, #cv-rings, #cv-back, #cv-front { position: absolute; inset: 0; }
#cv-badge, #cv-emote, #cv-rays { position: absolute; }
#cv-badge-in, #cv-emote-in { position: absolute; inset: 0; }
#cv-badge img, #cv-emote img {
  display: block; width: 100%; height: 100%; object-fit: contain;
  filter: drop-shadow(0 4px 0 rgba(0,0,0,0.35)) drop-shadow(0 8px 10px rgba(0,0,0,0.4));
}
#cv-rays {
  border-radius: 50%; opacity: 0;
  background: repeating-conic-gradient(from 0deg, rgba(252,223,181,0.55) 0deg 9deg, rgba(252,223,181,0) 9deg 24deg);
  -webkit-mask-image: radial-gradient(circle, #000 0 30%, rgba(0,0,0,0) 70%);
  mask-image: radial-gradient(circle, #000 0 30%, rgba(0,0,0,0) 70%);
}
.cv-ring { position: absolute; border-radius: 50%; opacity: 0; border: 7px solid var(--cream);
  box-shadow: 0 0 0 3px #000, inset 0 0 0 3px #000; }
.cv-px { position: absolute; border: 2px solid #000; opacity: 0; }
.cv-drop { position: absolute; width: 4px; background: #aab4bf; border-left: 1px solid #5b636b; border-right: 1px solid #5b636b; opacity: 0; }
.cv-cloud { position: absolute; opacity: 0; }
.cv-spark { position: absolute; opacity: 0; background: #fff;
  clip-path: polygon(50% 0, 62% 38%, 100% 50%, 62% 62%, 50% 100%, 38% 62%, 0 50%, 38% 38%); }
#cv-flash { position: absolute; border-radius: 50%; opacity: 0;
  background: radial-gradient(circle, #fff 0 40%, rgba(255,255,255,0.7) 55%, rgba(255,255,255,0) 70%); }

