  gsap.set("#cv-badge-in", { transformOrigin: "50% 60%" });
  tl.fromTo("#cv-badge-in", { scale: 2.4, rotation: tilt - 14, opacity: 0 }, { scale: 0.9, rotation: tilt, duration: T, ease: "power3.in" }, 0);
  tl.fromTo("#cv-badge-in", { opacity: 0 }, { opacity: 1, duration: 0.05, ease: "none", immediateRender: false }, 0.005);
  tl.to("#cv-badge-in", { keyframes: [{ scale: 1.08, duration: 0.08, ease: "power2.out" }, { scale: 1, duration: 0.14, ease: "power1.inOut" }] }, T);
  var sh = Math.max(3, bh * 0.035);
  tl.fromTo(badge, { x: 0, y: 0 }, { keyframes: [
    { x: -sh, y: sh, duration: 0.03 }, { x: sh, y: -sh * 0.6, duration: 0.03 }, { x: -sh * 0.5, y: sh * 0.4, duration: 0.03 },
    { x: sh * 0.3, y: 0, duration: 0.03 }, { x: 0, y: 0, duration: 0.03 }], ease: "none", immediateRender: false }, T);
  tl.fromTo(flash, { scale: 0.3, opacity: 0 }, { keyframes: [
    { scale: 0.9, opacity: 0.9, duration: 0.05, ease: "power2.out" }, { scale: 1.2, opacity: 0, duration: 0.18, ease: "power1.in" }] }, T);
  ringEls.forEach(function (rg, k) {
    tl.fromTo(rg, { scale: 0.6, opacity: 0 }, { keyframes: [
      { scale: 0.75, opacity: 1, duration: 0.03, ease: "none" },
      { scale: 2.1 + k * 0.45, opacity: 0, duration: 0.42 + k * 0.06, ease: "power2.out" }] }, T + k * 0.07);
  });
  // hold: gentle heartbeat (win/neutral) or a sad droop (lose)
  var HOLD0 = T + 0.3;
  if (mood === "lose") {
    tl.to("#cv-badge-in", { rotation: tilt + 7, y: bh * 0.05, duration: 0.5, ease: "power2.inOut" }, HOLD0);
  } else {
    var n = Math.max(1, Math.floor((OUT - HOLD0) / 0.36));
    tl.fromTo("#cv-badge-in", { scale: 1 }, { scale: 1.05, duration: (OUT - HOLD0) / (2 * n), ease: "sine.inOut", yoyo: true, repeat: 2 * n - 1, immediateRender: false }, HOLD0);
  }
  tl.to("#cv-badge-in", { keyframes: [{ scale: 1.12, duration: 0.06, ease: "power1.out" }, { scale: 0, opacity: 0, duration: END - OUT - 0.08, ease: "back.in(1.6)" }] }, OUT + 0.02);

  /* ---- mood effects */
  var back = document.getElementById("cv-back"), front = document.getElementById("cv-front");
  if (mood === "win") {
    tl.fromTo(rays, { scale: 0.4, opacity: 0, rotation: 0 }, { scale: 1, opacity: 0.85, rotation: 25, duration: 0.3, ease: "power2.out" }, T);
    tl.to(rays, { rotation: 70, duration: OUT - T - 0.3, ease: "none" }, T + 0.3);
    tl.to(rays, { opacity: 0, scale: 0.6, duration: 0.2, ease: "power1.in" }, OUT);
    var cols = [C.lime, C.orange, C.cream, C.leaf, C.diamond, C.paper];
    for (var k = 0; k < 44; k++) {
      var p = mk("cv-px", k % 3 ? front : back);
      var s = Math.round(6 + rnd() * 7);
      p.style.width = s + "px"; p.style.height = Math.round(s * (0.6 + rnd() * 0.6)) + "px";
      p.style.background = cols[k % cols.length];
      box(p, cx - s / 2, cy - s / 2, s, s * (0.6 + rnd() * 0.6));
      var a = -Math.PI / 2 + (rnd() - 0.5) * Math.PI * 1.9, sp = R * (1.2 + rnd() * 1.6);
      var dx = Math.cos(a) * sp * (d.vertical ? 0.9 : 1.3), dy = Math.sin(a) * sp - R * 0.3;
      var fall = H * (0.18 + rnd() * 0.22), t0 = T + 0.01 + rnd() * 0.05, spin = (rnd() < 0.5 ? -1 : 1) * (360 + rnd() * 540);
      var tFall = OUT + 0.1 - t0 - 0.32;
      tl.fromTo(p, { x: 0, y: 0, rotation: 0, opacity: 0, scale: 0.4 }, { keyframes: [
        { x: dx, y: dy, opacity: 1, scale: 1, rotation: spin * 0.35, duration: 0.32, ease: "power3.out" },
        { x: dx * 1.25 + (rnd() - 0.5) * 30, y: dy + fall, rotation: spin, duration: tFall, ease: "power1.in" },
        { opacity: 0, duration: 0.12, ease: "none" }] }, t0);
    }
  } else if (mood === "lose") {
    // grey pixel rain cloud over the badge
    var cloudRows = ["....aaaa........", "..aabbbbaa.aaa..", ".abbbbbbbbabbba.", "abbbbbbbbbbbbbba", "acccbbbbbcccbbca", ".acccccccccccca."];
    var cw = Math.min(W * 0.7, bw * 1.9), px = cw / 16;
    var cloud = mk("cv-cloud", front);
    cloud.innerHTML = MC.pixelSVG(cloudRows, { a: "#2b3036", b: "#9aa3ab", c: "#6d757d" }, px);
    var cy0 = cy - bh * 0.5 - px * 6 - bh * 0.08;
    box(cloud, cx - cw / 2, cy0, cw, px * 6);
    tl.fromTo(cloud, { y: -40, opacity: 0, scale: 0.6 }, { y: 0, opacity: 1, scale: 1, duration: 0.3, ease: "back.out(2)" }, T + 0.06);
    tl.fromTo(cloud, { x: 0 }, { x: 6, duration: 0.25, ease: "sine.inOut", yoyo: true, repeat: 3, immediateRender: false }, T + 0.36);
    tl.to(cloud, { opacity: 0, y: -20, duration: 0.18, ease: "power1.in" }, OUT);
    var rainTop = cy0 + px * 5, rainLen = bh * 1.2 + px * 2;
    for (var j = 0; j < 22; j++) {
      var dr = mk("cv-drop", j % 2 ? front : back);
      var dh = 10 + rnd() * 10;
      box(dr, cx - cw * 0.42 + rnd() * cw * 0.84, rainTop, 4, dh);
      var per = 0.32 + rnd() * 0.12, st = T + 0.25 + rnd() * per;
      var reps = Math.max(1, Math.floor((OUT - st) / per));
      tl.fromTo(dr, { y: 0, opacity: 0.95 }, { y: rainLen, duration: per, ease: "power1.in", repeat: reps - 1 }, st);
      tl.set(dr, { opacity: 0 }, st + reps * per);
    }
  } else {
    for (var q = 0; q < 8; q++) {
      var sp2 = mk("cv-spark", front);
      var ss = 10 + rnd() * 14, ang = (q / 8) * Math.PI * 2 + rnd() * 0.4, rr = R * (1.05 + rnd() * 0.4);
      box(sp2, cx + Math.cos(ang) * rr - ss / 2, cy + Math.sin(ang) * rr - ss / 2, ss, ss);
      sp2.style.background = q % 2 ? C.cream : "#ffffff";
      var t1 = T + 0.05 + rnd() * 0.5;
      tl.fromTo(sp2, { scale: 0, opacity: 0, rotation: 0 }, { keyframes: [
        { scale: 1.2, opacity: 1, rotation: 45, duration: 0.18, ease: "back.out(3)" },
        { scale: 0, opacity: 0, rotation: 90, duration: 0.3, ease: "power1.in" }] }, t1);
      if (t1 + 0.75 < OUT) tl.fromTo(sp2, { scale: 0, opacity: 0 }, { keyframes: [
        { scale: 1, opacity: 1, duration: 0.15, ease: "back.out(3)" }, { scale: 0, opacity: 0, duration: 0.25 }], immediateRender: false }, t1 + 0.55);
    }
  }

  /* ---- reacting emote */
  if (eSrc) {
    var ET = 0.36;
    gsap.set("#cv-emote-in", { transformOrigin: "50% 90%" });
    tl.fromTo("#cv-emote-in", { scale: 0, rotation: -25, y: eh * 0.3 }, {
      keyframes: [{ scale: 1.18, rotation: 8, y: 0, duration: 0.16, ease: "power2.out" },
                  { scale: 0.94, rotation: 4, duration: 0.08 }, { scale: 1, rotation: 6, duration: 0.1 }] }, ET);
    var wigN = Math.max(1, Math.floor((OUT - ET - 0.4) / 0.2));
    var wig = [];
    for (var w = 0; w < wigN; w++) wig.push(mood === "lose" ? { y: (w % 2 ? 0 : eh * 0.04), rotation: 6 + (w % 2 ? -2 : 2), duration: (OUT - ET - 0.4) / wigN, ease: "sine.inOut" }
                                                           : { y: (w % 2 ? 0 : -eh * 0.08), rotation: w % 2 ? 2 : 10, duration: (OUT - ET - 0.4) / wigN, ease: "sine.inOut" });
    tl.to("#cv-emote-in", { keyframes: wig }, ET + 0.38);
    tl.to("#cv-emote-in", { scale: 0, rotation: 40, duration: 0.18, ease: "back.in(2)" }, OUT - 0.04);
  }
  tl.set("#cv-all", { opacity: 0 }, END);
  return tl;
});

