{
  "description": "2.5s day counter: a pixel grass-block plinth rises with 'DAY' + a big number on its face, Crodie drops on top and sits, the number ticks from -> to, and a crown pops onto Crodie's head on the final tick with a sparkle burst.",
  "kind": "overlay",
  "duration": 2.5,
  "orientations": ["landscape", "vertical"],
  "vars": {
    "label":    {"type": "string", "label": "Label above the number (empty = none)", "default": "DAY"},
    "from":     {"type": "number", "label": "Start value", "default": 1},
    "to":       {"type": "number", "label": "End value", "default": 47},
    "mascot":   {"type": "string", "label": "Crodie sitting on the plinth (local path). e.g. brand/crodie/characters/char_king_robe_scepter.png (already crowned: set crown to \"\"). Empty = none", "default": "brand/crodie/characters/char_diamond_sitting.png"},
    "crown":    {"type": "string", "label": "Crown that pops onto the head on the last tick (local path, empty = none)", "default": "brand/crodie/logos/crown_1.png"},
    "crown_x":  {"type": "number", "label": "Crown centre as a fraction of the mascot width (0.38 suits char_diamond_sitting; 0.5 for centred heads)", "default": 0.38},
    "position": {"type": "string", "label": "center | left | right", "default": "center"},
    "opaque":   {"type": "boolean", "label": "Opaque ink background", "default": false}
  }
}

