#dc-group { position: absolute; left: 0; top: 0; }
#dc-plinth, #dc-mascot, #dc-crown, #dc-glow { position: absolute; }
#dc-mascot-in, #dc-crown-in { position: absolute; inset: 0; }
#dc-mascot img, #dc-crown img {
  display: block; width: 100%; height: 100%; object-fit: contain;
  filter: drop-shadow(0 3px 0 rgba(0,0,0,0.35)) drop-shadow(0 6px 8px rgba(0,0,0,0.35));
}
#dc-face {
  position: absolute; left: 0; right: 0; bottom: 0;
  background-size: 100% 100%; image-rendering: pixelated;
  border: 4px solid #000;
  box-shadow: inset 5px 5px 0 rgba(255,255,255,0.18), inset -5px -5px 0 rgba(0,0,0,0.3), 8px 9px 0 rgba(0,0,0,0.45);
}
#dc-top {
  position: absolute; left: 0; right: 0; top: 0;
  background-size: 100% 100%; image-rendering: pixelated;
  border: 4px solid #000; border-bottom: none;
  transform-origin: 50% 100%;
}
#dc-label { position: absolute; left: 0; width: 100%; text-align: center; color: var(--cream); line-height: 1; white-space: nowrap; }
#dc-num { position: absolute; left: 0; width: 100%; text-align: center; color: var(--paper); line-height: 1; white-space: nowrap; }
#dc-glow { border-radius: 50%; opacity: 0;
  background: radial-gradient(circle, rgba(255,214,120,0.85) 0 20%, rgba(239,119,24,0.35) 45%, rgba(239,119,24,0) 70%); }
#dc-bits { position: absolute; inset: 0; }
.dc-bit { position: absolute; border: 2px solid #000; opacity: 0; }
.dc-spark { position: absolute; opacity: 0; background: #fff;
  clip-path: polygon(50% 0, 62% 38%, 100% 50%, 62% 62%, 50% 100%, 38% 62%, 0 50%, 38% 38%); }

