MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h, D = d.duration;
  var rnd = MC.rng(4747);
  var C = { lime: MC.css("--grass") || "#92AE22", leaf: MC.css("--leaf") || "#437420", orange: MC.css("--gold") || "#EF7718",
            cream: MC.css("--cream") || "#FCDFB5", paper: MC.css("--paper") || "#FCF3E2", diamond: MC.css("--diamond") || "#4FE0D6" };
  var from = MC.num(v.from, 1), to = MC.num(v.to, 47);
  var label = String(v.label == null ? "" : v.label).toUpperCase().trim();
  var pos = String(v.position || "center").trim().toLowerCase();
  if (["center", "left", "right"].indexOf(pos) < 0) pos = "center";
  function fmt(x) { return String(Math.round(x)); }

  /* ---- images */
  function uri(x, what) {
    var s = String(x == null ? "" : x).trim();
    if (s && !/^(data:|https?:|blob:)/i.test(s)) { console.warn("crodie_day_counter: " + what + " path did not resolve; skipped"); return ""; }
    return s;
  }
  function imgSize(u) {
    var m = /^data:[^;,]*;base64,(.*)$/i.exec(u || "");
    if (!m) return null;
    var h; try { h = atob(m[1].slice(0, 64)); } catch (e) { return null; }
    var b = function (i) { return h.charCodeAt(i) & 255; };
    if (h.slice(1, 4) === "PNG") return [(b(16) << 24 | b(17) << 16 | b(18) << 8 | b(19)) >>> 0, (b(20) << 24 | b(21) << 16 | b(22) << 8 | b(23)) >>> 0];
    if (h.slice(0, 3) === "GIF") return [b(6) | b(7) << 8, b(8) | b(9) << 8];
    if (h.slice(0, 4) === "RIFF" && h.slice(12, 16) === "VP8X") return [(b(24) | b(25) << 8 | b(26) << 16) + 1, (b(27) | b(28) << 8 | b(29) << 16) + 1];
    return null;
  }
  function put(el, s) {
    if (!s) return;
    var img = document.createElement("img"); img.src = s; img.alt = "";
    img.setAttribute("data-layout-allow-overflow", "");
    el.appendChild(img);
  }
  function box(el, x, y, w, h) {
    el.style.left = x.toFixed(1) + "px"; el.style.top = y.toFixed(1) + "px";
    el.style.width = w.toFixed(1) + "px"; el.style.height = h.toFixed(1) + "px";
  }
  function mk(cls, parent) {
    var e = document.createElement("div"); e.className = cls;
    e.setAttribute("data-layout-allow-overlap", ""); e.setAttribute("data-layout-allow-overflow", "");
    parent.appendChild(e); return e;
  }
  var mSrc = uri(v.mascot, "mascot"), cSrc = uri(v.crown, "crown");
  var mN = imgSize(mSrc) || [258, 277], cN = imgSize(cSrc) || [157, 135];

  /* ---- grass-block textures (seeded, 16 px wide) */
  function tex(w, h, grassRows, seed, light) {
    var r = MC.rng(seed), cv = document.createElement("canvas"); cv.width = w; cv.height = h;
    var cx = cv.getContext("2d");
    var g = light ? [MC.shade(C.lime, 0.1), C.lime, MC.shade(C.lime, 0.22), MC.mix(C.lime, C.leaf, 0.4), MC.mix(C.lime, C.orange, 0.6)]
                  : [C.lime, MC.mix(C.lime, C.leaf, 0.45), MC.shade(C.lime, 0.12), C.leaf, MC.mix(C.lime, C.orange, 0.7)];
    var dirt = ["#9a5a2c", "#87491f", "#b06a34", "#6e3c1a", "#c27b3e"];
    var drip = [];
    for (var x = 0; x < w; x++) drip.push(grassRows + Math.floor(r() * 3) - (r() < 0.3 ? 1 : 0));
    for (var y = 0; y < h; y++) for (var x2 = 0; x2 < w; x2++) {
      var q = r(), k = q < 0.42 ? 0 : q < 0.62 ? 1 : q < 0.8 ? 2 : q < 0.93 ? 3 : 4;
      cx.fillStyle = (y < drip[x2]) ? g[k] : dirt[k]; cx.fillRect(x2, y, 1, 1);
    }
    return 'url("' + cv.toDataURL("image/png") + '")';
  }

  /* ---- layout */
  var K = 0.6;
  var digits = Math.max(fmt(from).length, fmt(to).length, 2);
  var numSize = Math.floor(Math.min(d.vertical ? 104 : 92, (d.vertical ? 330 : 300) / (digits * K)));
  var labSize = label ? Math.floor(Math.min(numSize * 0.42, 40)) : 0;
  var faceW = Math.max(d.vertical ? 250 : 230, digits * numSize * K + numSize * 0.9, label.length * labSize * 0.6 + 60);
  faceW = Math.min(faceW, W * (d.vertical ? 0.86 : 0.6));
  var grassH = Math.round(numSize * 0.32);
  var faceH = Math.round(grassH + labSize * (label ? 1.15 : 0) + numSize * 1.12 + 18);
  var topH = Math.round(faceW * 0.1);
  var mh = Math.min(d.vertical ? 200 : 180, mN[1] * 0.9), mw = mh * mN[0] / mN[1];
  var ch = Math.min(mh * 0.3, cN[1] * 0.9), cw = ch * cN[0] / cN[1];

  var gw = Math.max(faceW, mw), totalH = faceH + topH + mh * 0.94 + (cSrc ? ch * 0.6 : 0);
  var bottom = d.vertical ? H * 0.70 : H * 0.9;                     // vertical: above the caption zone
  var top0 = Math.max(d.vertical ? H * 0.12 : H * 0.05, bottom - totalH);
  var gcx = pos === "left" ? Math.max(gw / 2 + W * 0.04, W * 0.2) : pos === "right" ? Math.min(W - gw / 2 - W * 0.04, W * 0.8) : W / 2;
  var plTop = top0 + totalH - faceH - topH;

  var plinth = document.getElementById("dc-plinth");
  box(plinth, gcx - faceW / 2, plTop, faceW, faceH + topH);
  plinth.style.zIndex = 1;
  var face = document.getElementById("dc-face"), topF = document.getElementById("dc-top");
  face.style.height = faceH + "px";
  face.style.backgroundImage = tex(16, Math.max(8, Math.round(16 * faceH / faceW)), Math.max(2, Math.round(16 * grassH / faceW)), 91, false);
  topF.style.height = (topH + 2) + "px";
  topF.style.backgroundImage = tex(16, 3, 9, 92, true);
  gsap.set(topF, { skewX: -30, scaleX: 0.93, x: topH * 0.25 });

  var lab = document.getElementById("dc-label"), num = document.getElementById("dc-num");
  lab.textContent = label; lab.style.fontSize = labSize + "px";
  lab.style.top = (grassH + 6) + "px";
  if (!label) lab.style.display = "none";
