  var mascot = document.getElementById("dc-mascot");
  var mx = gcx - mw / 2 + faceW * 0.02, my = plTop + topH * 0.75 - mh * 0.94;
  box(mascot, mx, my, mw, mh);
  mascot.style.zIndex = 2;
  put(document.getElementById("dc-mascot-in"), mSrc);
  var cx0 = mx + mw * Math.max(0, Math.min(1, MC.num(v.crown_x, 0.38))), cy0 = my - ch * 0.35;
  var crown = document.getElementById("dc-crown");
  box(crown, cx0 - cw / 2, cy0, cw, ch);
  crown.style.zIndex = 3;
  put(document.getElementById("dc-crown-in"), cSrc);
  var glow = document.getElementById("dc-glow"), GR = ch * 1.6;
  box(glow, cx0 - GR, cy0 + ch / 2 - GR, GR * 2, GR * 2);

  /* ---- timeline */
  var tl = gsap.timeline({ paused: true });
  tl.set("#dc-group", { opacity: 1 }, 0);
  gsap.set(plinth, { transformOrigin: "50% 100%" });
  tl.fromTo(plinth, { y: 70, scaleY: 0.2, scaleX: 0.6, opacity: 0 }, { y: 0, scaleY: 1, scaleX: 1, opacity: 1, duration: 0.32, ease: "back.out(2)" }, 0);
  if (label) tl.fromTo(lab, { scale: 0, y: 10 }, { scale: 1, y: 0, duration: 0.24, ease: "back.out(3)" }, 0.22);
  tl.fromTo(num, { scale: 0 }, { scale: 1, duration: 0.24, ease: "back.out(3)" }, 0.26);

  var mIn = document.getElementById("dc-mascot-in");
  gsap.set(mIn, { transformOrigin: "50% 100%" });
  if (mSrc) {
    tl.fromTo(mIn, { y: -H * 0.5, opacity: 0, scaleX: 1, scaleY: 1 }, { y: 0, opacity: 1, duration: 0.26, ease: "power2.in" }, 0.16);
    tl.to(mIn, { keyframes: [{ scaleY: 0.8, scaleX: 1.14, duration: 0.07, ease: "power2.out" }, { scaleY: 1.06, scaleX: 0.96, duration: 0.09 }, { scaleY: 1, scaleX: 1, duration: 0.1 }] }, 0.42);
