  tl.fromTo(plinth, { rotation: 0 }, { keyframes: [{ rotation: -2.5, duration: 0.08 }, { rotation: 1.5, duration: 0.08 }, { rotation: 0, duration: 0.1 }], immediateRender: false }, LAND);
  if (mSrc) tl.to(mIn, { keyframes: [{ y: -mh * 0.12, scaleY: 1.05, duration: 0.12, ease: "power2.out" }, { y: 0, scaleY: 1, duration: 0.16, ease: "bounce.out" }] }, LAND);
  var cIn = document.getElementById("dc-crown-in");
  if (cSrc) {
    gsap.set(cIn, { transformOrigin: "50% 100%" });
    tl.fromTo(cIn, { y: -ch * 2.2, scale: 1.6, rotation: -30, opacity: 0 }, { y: 0, scale: 1, rotation: -8, opacity: 1, duration: 0.22, ease: "back.out(2.2)" }, LAND + 0.04);
    tl.fromTo(glow, { scale: 0.2, opacity: 0 }, { keyframes: [{ scale: 1, opacity: 1, duration: 0.12, ease: "power2.out" }, { scale: 1.4, opacity: 0, duration: 0.4, ease: "power1.in" }] }, LAND + 0.1);
    var nb = Math.max(1, Math.floor((D - 0.3 - LAND - 0.35) / 0.3));
    tl.fromTo(cIn, { rotation: -8 }, { rotation: -2, duration: (D - 0.3 - LAND - 0.35) / (2 * nb), ease: "sine.inOut", yoyo: true, repeat: 2 * nb - 1, immediateRender: false }, LAND + 0.3);
  }
  var bits = document.getElementById("dc-bits"), bcols = [C.lime, C.orange, C.cream, C.diamond];
  var bx = gcx, by = plTop + topH + faceH * 0.55;
