    b.style.background = bcols[i % bcols.length];
    var a = (i / 14) * Math.PI * 2 + rnd() * 0.3, rr = faceW * (0.55 + rnd() * 0.35);
    tl.fromTo(b, { x: 0, y: 0, opacity: 1, scale: 1, rotation: 0 },
