  }
  var sparkTargets = cSrc ? [cx0, cy0 + ch * 0.4] : [gcx, plTop];
  for (var j = 0; j < 6; j++) {
    var sp = mk("dc-spark", bits), ss = 9 + rnd() * 10;
    var ang = (j / 6) * Math.PI * 2 + 0.3, rad = Math.max(cw, 40) * (0.8 + rnd() * 0.5);
    box(sp, sparkTargets[0] + Math.cos(ang) * rad - ss / 2, sparkTargets[1] + Math.sin(ang) * rad * 0.7 - ss / 2, ss, ss);
    sp.style.background = j % 2 ? C.cream : "#fff";
    tl.fromTo(sp, { scale: 0, opacity: 0, rotation: 0 }, { keyframes: [
      { scale: 1.2, opacity: 1, rotation: 45, duration: 0.16, ease: "back.out(3)" }, { scale: 0, opacity: 0, rotation: 90, duration: 0.3 }] }, LAND + 0.1 + j * 0.04);
  }

  // exit
  var OUT = D - 0.28, END = D - 0.04;
  if (cSrc) tl.to(cIn, { y: -30, opacity: 0, duration: 0.16, ease: "power2.in" }, OUT);
  if (mSrc) tl.to(mIn, { y: -mh * 0.25, scale: 0, duration: 0.2, ease: "back.in(2)" }, OUT + 0.02);
  tl.to(plinth, { scaleY: 0, scaleX: 0.5, y: 40, opacity: 0, duration: 0.22, ease: "back.in(1.8)" }, OUT + 0.02);
  tl.set("#dc-group", { opacity: 0 }, END);
  return tl;
});

