MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h, D = d.duration;
  var rnd = MC.rng(4747);
  var C = { lime: MC.css("--grass") || "#92AE22", leaf: MC.css("--leaf") || "#437420", orange: MC.css("--gold") || "#EF7718",
            cream: MC.css("--cream") || "#FCDFB5", paper: MC.css("--paper") || "#FCF3E2", diamond: MC.css("--diamond") || "#4FE0D6" };
  var from = MC.num(v.from, 1), to = MC.num(v.to, 47);
  var label = String(v.label == null ? "" : v.label).toUpperCase().trim();
  var pos = String(v.position || "center").trim().toLowerCase();
  if (["center", "left", "right"].indexOf(pos) < 0) pos = "center";
  function fmt(x) { return String(Math.round(x)); }

  /* ---- images */
  function uri(x, what) {
    var s = String(x == null ? "" : x).trim();
    if (s && !/^(data:|https?:|blob:)/i.test(s)) { console.warn("crodie_day_counter: " + what + " path did not resolve; skipped"); return ""; }
    return s;
  }
  function imgSize(u) {
    var m = /^data:[^;,]*;base64,(.*)$/i.exec(u || "");
    if (!m) return null;
    var h; try { h = atob(m[1].slice(0, 64)); } catch (e) { return null; }
    var b = function (i) { return h.charCodeAt(i) & 255; };
    if (h.slice(1, 4) === "PNG") return [(b(16) << 24 | b(17) << 16 | b(18) << 8 | b(19)) >>> 0, (b(20) << 24 | b(21) << 16 | b(22) << 8 | b(23)) >>> 0];
    if (h.slice(0, 3) === "GIF") return [b(6) | b(7) << 8, b(8) | b(9) << 8];
    if (h.slice(0, 4) === "RIFF" && h.slice(12, 16) === "VP8X") return [(b(24) | b(25) << 8 | b(26) << 16) + 1, (b(27) | b(28) << 8 | b(29) << 16) + 1];
    return null;
  }
  function put(el, s) {
    if (!s) return;
    var img = document.createElement("img"); img.src = s; img.alt = "";
    img.setAttribute("data-layout-allow-overflow", "");
    el.appendChild(img);
  }
  function box(el, x, y, w, h) {
    el.style.left = x.toFixed(1) + "px"; el.style.top = y.toFixed(1) + "px";
    el.style.width = w.toFixed(1) + "px"; el.style.height = h.toFixed(1) + "px";
  }
  function mk(cls, parent) {
    var e = document.createElement("div"); e.className = cls;
    e.setAttribute("data-layout-allow-overlap", ""); e.setAttribute("data-layout-allow-overflow", "");
    parent.appendChild(e); return e;
  }
  var mSrc = uri(v.mascot, "mascot"), cSrc = uri(v.crown, "crown");
  var mN = imgSize(mSrc) || [258, 277], cN = imgSize(cSrc) || [157, 135];

  /* ---- grass-block textures (seeded, 16 px wide) */
  function tex(w, h, grassRows, seed, light) {
    var r = MC.rng(seed), cv = document.createElement("canvas"); cv.width = w; cv.height = h;
    var cx = cv.getContext("2d");
    var g = light ? [MC.shade(C.lime, 0.1), C.lime, MC.shade(C.lime, 0.22), MC.mix(C.lime, C.leaf, 0.4), MC.mix(C.lime, C.orange, 0.6)]
                  : [C.lime, MC.mix(C.lime, C.leaf, 0.45), MC.shade(C.lime, 0.12), C.leaf, MC.mix(C.lime, C.orange, 0.7)];
    var dirt = ["#9a5a2c", "#87491f", "#b06a34", "#6e3c1a", "#c27b3e"];
    var drip = [];
    for (var x = 0; x < w; x++) drip.push(grassRows + Math.floor(r() * 3) - (r() < 0.3 ? 1 : 0));
    for (var y = 0; y < h; y++) for (var x2 = 0; x2 < w; x2++) {
      var q = r(), k = q < 0.42 ? 0 : q < 0.62 ? 1 : q < 0.8 ? 2 : q < 0.93 ? 3 : 4;
      cx.fillStyle = (y < drip[x2]) ? g[k] : dirt[k]; cx.fillRect(x2, y, 1, 1);
    }
    return 'url("' + cv.toDataURL("image/png") + '")';
  }

  /* ---- layout */
  var K = 0.6;
  var digits = Math.max(fmt(from).length, fmt(to).length, 2);
  var numSize = Math.floor(Math.min(d.vertical ? 104 : 92, (d.vertical ? 330 : 300) / (digits * K)));
  var labSize = label ? Math.floor(Math.min(numSize * 0.42, 40)) : 0;
  var faceW = Math.max(d.vertical ? 250 : 230, digits * numSize * K + numSize * 0.9, label.length * labSize * 0.6 + 60);
  faceW = Math.min(faceW, W * (d.vertical ? 0.86 : 0.6));
  var grassH = Math.round(numSize * 0.32);
  var faceH = Math.round(grassH + labSize * (label ? 1.15 : 0) + numSize * 1.12 + 18);
  var topH = Math.round(faceW * 0.1);
  var mh = Math.min(d.vertical ? 200 : 180, mN[1] * 0.9), mw = mh * mN[0] / mN[1];
  var ch = Math.min(mh * 0.3, cN[1] * 0.9), cw = ch * cN[0] / cN[1];

  var gw = Math.max(faceW, mw), totalH = faceH + topH + mh * 0.94 + (cSrc ? ch * 0.6 : 0);
  var bottom = d.vertical ? H * 0.70 : H * 0.9;                     // vertical: above the caption zone
  var top0 = Math.max(d.vertical ? H * 0.12 : H * 0.05, bottom - totalH);
  var gcx = pos === "left" ? Math.max(gw / 2 + W * 0.04, W * 0.2) : pos === "right" ? Math.min(W - gw / 2 - W * 0.04, W * 0.8) : W / 2;
  var plTop = top0 + totalH - faceH - topH;

  var plinth = document.getElementById("dc-plinth");
  box(plinth, gcx - faceW / 2, plTop, faceW, faceH + topH);
  plinth.style.zIndex = 1;
  var face = document.getElementById("dc-face"), topF = document.getElementById("dc-top");
  face.style.height = faceH + "px";
  face.style.backgroundImage = tex(16, Math.max(8, Math.round(16 * faceH / faceW)), Math.max(2, Math.round(16 * grassH / faceW)), 91, false);
  topF.style.height = (topH + 2) + "px";
  topF.style.backgroundImage = tex(16, 3, 9, 92, true);
  gsap.set(topF, { skewX: -30, scaleX: 0.93, x: topH * 0.25 });

  var lab = document.getElementById("dc-label"), num = document.getElementById("dc-num");
  lab.textContent = label; lab.style.fontSize = labSize + "px";
  lab.style.top = (grassH + 6) + "px";
  if (!label) lab.style.display = "none";
  num.style.fontSize = numSize + "px";
  num.style.top = (grassH + (label ? labSize * 1.15 : 0) + 6 + numSize * 0.04) + "px";
  num.textContent = fmt(from);

  var mascot = document.getElementById("dc-mascot");
  var mx = gcx - mw / 2 + faceW * 0.02, my = plTop + topH * 0.75 - mh * 0.94;
  box(mascot, mx, my, mw, mh);
  mascot.style.zIndex = 2;
  put(document.getElementById("dc-mascot-in"), mSrc);
  var cx0 = mx + mw * Math.max(0, Math.min(1, MC.num(v.crown_x, 0.38))), cy0 = my - ch * 0.35;
  var crown = document.getElementById("dc-crown");
  box(crown, cx0 - cw / 2, cy0, cw, ch);
  crown.style.zIndex = 3;
  put(document.getElementById("dc-crown-in"), cSrc);
  var glow = document.getElementById("dc-glow"), GR = ch * 1.6;
  box(glow, cx0 - GR, cy0 + ch / 2 - GR, GR * 2, GR * 2);

  /* ---- timeline */
  var tl = gsap.timeline({ paused: true });
  tl.set("#dc-group", { opacity: 1 }, 0);
  gsap.set(plinth, { transformOrigin: "50% 100%" });
  tl.fromTo(plinth, { y: 70, scaleY: 0.2, scaleX: 0.6, opacity: 0 }, { y: 0, scaleY: 1, scaleX: 1, opacity: 1, duration: 0.32, ease: "back.out(2)" }, 0);
  if (label) tl.fromTo(lab, { scale: 0, y: 10 }, { scale: 1, y: 0, duration: 0.24, ease: "back.out(3)" }, 0.22);
  tl.fromTo(num, { scale: 0 }, { scale: 1, duration: 0.24, ease: "back.out(3)" }, 0.26);

  var mIn = document.getElementById("dc-mascot-in");
  gsap.set(mIn, { transformOrigin: "50% 100%" });
  if (mSrc) {
    tl.fromTo(mIn, { y: -H * 0.5, opacity: 0, scaleX: 1, scaleY: 1 }, { y: 0, opacity: 1, duration: 0.26, ease: "power2.in" }, 0.16);
    tl.to(mIn, { keyframes: [{ scaleY: 0.8, scaleX: 1.14, duration: 0.07, ease: "power2.out" }, { scaleY: 1.06, scaleX: 0.96, duration: 0.09 }, { scaleY: 1, scaleX: 1, duration: 0.1 }] }, 0.42);
    tl.to(plinth, { keyframes: [{ y: 6, duration: 0.06 }, { y: 0, duration: 0.12, ease: "back.out(3)" }] }, 0.42);
  }

  // the tick (seek-safe: text is a pure function of tween progress)
  var T0 = 0.5, TD = 1.1, LAND = T0 + TD;
  var proxy = { v: from };
  tl.fromTo(proxy, { v: from }, { v: to, duration: TD, ease: "power2.inOut", onUpdate: function () { num.textContent = fmt(proxy.v); } }, T0);
  var nT = Math.max(2, Math.floor(TD / 0.08));
  tl.fromTo(num, { y: 0 }, { y: -3, duration: 0.04, ease: "steps(1)", yoyo: true, repeat: nT * 2 - 1, immediateRender: false }, T0);
  if (mSrc) tl.fromTo(mIn, { rotation: 0 }, { rotation: 3, duration: TD / 8, ease: "sine.inOut", yoyo: true, repeat: 7, immediateRender: false }, T0);

  // land: punch, orange flash, crown + sparkles + bits
  tl.fromTo(num, { scale: 1.35 }, { scale: 1, duration: 0.32, ease: "back.out(3)", immediateRender: false }, LAND);
  tl.fromTo(num, { color: C.paper }, { color: C.orange, duration: 0.04, immediateRender: false }, LAND);
  tl.fromTo(plinth, { rotation: 0 }, { keyframes: [{ rotation: -2.5, duration: 0.08 }, { rotation: 1.5, duration: 0.08 }, { rotation: 0, duration: 0.1 }], immediateRender: false }, LAND);
  if (mSrc) tl.to(mIn, { keyframes: [{ y: -mh * 0.12, scaleY: 1.05, duration: 0.12, ease: "power2.out" }, { y: 0, scaleY: 1, duration: 0.16, ease: "bounce.out" }] }, LAND);
  var cIn = document.getElementById("dc-crown-in");
  if (cSrc) {
    gsap.set(cIn, { transformOrigin: "50% 100%" });
    tl.fromTo(cIn, { y: -ch * 2.2, scale: 1.6, rotation: -30, opacity: 0 }, { y: 0, scale: 1, rotation: -8, opacity: 1, duration: 0.22, ease: "back.out(2.2)" }, LAND + 0.04);
    tl.fromTo(glow, { scale: 0.2, opacity: 0 }, { keyframes: [{ scale: 1, opacity: 1, duration: 0.12, ease: "power2.out" }, { scale: 1.4, opacity: 0, duration: 0.4, ease: "power1.in" }] }, LAND + 0.1);
    var nb = Math.max(1, Math.floor((D - 0.3 - LAND - 0.35) / 0.3));
    tl.fromTo(cIn, { rotation: -8 }, { rotation: -2, duration: (D - 0.3 - LAND - 0.35) / (2 * nb), ease: "sine.inOut", yoyo: true, repeat: 2 * nb - 1, immediateRender: false }, LAND + 0.3);
  }
  var bits = document.getElementById("dc-bits"), bcols = [C.lime, C.orange, C.cream, C.diamond];
  var bx = gcx, by = plTop + topH + faceH * 0.55;
  for (var i = 0; i < 14; i++) {
    var b = mk("dc-bit", bits), s = Math.round(7 + rnd() * 6);
    box(b, bx - s / 2, by - s / 2, s, s);
    b.style.background = bcols[i % bcols.length];
    var a = (i / 14) * Math.PI * 2 + rnd() * 0.3, rr = faceW * (0.55 + rnd() * 0.35);
    tl.fromTo(b, { x: 0, y: 0, opacity: 1, scale: 1, rotation: 0 },
      { x: Math.cos(a) * rr, y: Math.sin(a) * rr * 0.75, opacity: 0, scale: 0.4, rotation: 200, duration: 0.5, ease: "power2.out", immediateRender: false }, LAND);
  }
  var sparkTargets = cSrc ? [cx0, cy0 + ch * 0.4] : [gcx, plTop];
  for (var j = 0; j < 6; j++) {
    var sp = mk("dc-spark", bits), ss = 9 + rnd() * 10;
    var ang = (j / 6) * Math.PI * 2 + 0.3, rad = Math.max(cw, 40) * (0.8 + rnd() * 0.5);
    box(sp, sparkTargets[0] + Math.cos(ang) * rad - ss / 2, sparkTargets[1] + Math.sin(ang) * rad * 0.7 - ss / 2, ss, ss);
