    tl.fromTo(sp, { scale: 0, opacity: 0, rotation: 0 }, { keyframes: [
      { scale: 1.2, opacity: 1, rotation: 45, duration: 0.16, ease: "back.out(3)" }, { scale: 0, opacity: 0, rotation: 90, duration: 0.3 }] }, LAND + 0.1 + j * 0.04);
  }

  // exit
  var OUT = D - 0.28, END = D - 0.04;
  if (cSrc) tl.to(cIn, { y: -30, opacity: 0, duration: 0.16, ease: "power2.in" }, OUT);
  if (mSrc) tl.to(mIn, { y: -mh * 0.25, scale: 0, duration: 0.2, ease: "back.in(2)" }, OUT + 0.02);
