#ec-scrim { position: absolute; inset: 0; opacity: 0;
  background: radial-gradient(ellipse at 50% 45%, var(--olive) 0%, var(--ink) 75%); }
#ec-logo, #ec-mascot, #ec-sub, #ec-sublabel, #ec-title { position: absolute; }
#ec-logo-in, #ec-mascot-in { position: absolute; inset: 0; }
#ec-logo img, #ec-mascot img, .ec-vine img {
  display: block; width: 100%; height: 100%; object-fit: contain;
  filter: drop-shadow(0 3px 0 rgba(0,0,0,0.35)) drop-shadow(0 6px 8px rgba(0,0,0,0.4));
}
#ec-title { color: var(--grass); text-align: center; line-height: 1; white-space: nowrap; }
/* Video slot: the rectangle itself is EMPTY; the wood bars sit outside it. */
.ec-frame { position: absolute; }
.ec-bar { position: absolute; background-size: 100% 100%; image-rendering: pixelated; border: 2px solid #000;
  box-shadow: inset 2px 2px 0 rgba(255,255,255,0.18), inset -2px -2px 0 rgba(0,0,0,0.35); }
.ec-shadow { position: absolute; background: rgba(0,0,0,0.45); }
.ec-moss { position: absolute; background-size: 100% 100%; image-rendering: pixelated; }
.ec-vine { position: absolute; }
.ec-label {
  position: absolute; white-space: nowrap; line-height: 1; color: var(--paper);
  background: var(--gold); border: 3px solid #000;
  box-shadow: inset 3px 3px 0 rgba(255,255,255,0.3), inset -3px -3px 0 rgba(0,0,0,0.28), 4px 4px 0 #000;
  text-shadow: 2px 2px 0 rgba(0,0,0,0.55);
}
.ec-stud { position: absolute; width: 8px; height: 8px; background: #3a2412; border: 1px solid #000; }
#ec-sub { border-radius: 50%; border: 7px solid var(--grass);
  box-shadow: 0 0 0 3px #000, inset 0 0 0 3px #000, 0 0 0 9px var(--leaf), 0 0 0 12px #000, 6px 8px 0 12px rgba(0,0,0,0.4); }
#ec-sublabel { color: var(--cream); white-space: nowrap; line-height: 1; }
.ec-leaf { position: absolute; }

