    box(el, fx, fy, fw, fh);
    var sh = [mk("ec-shadow", el), mk("ec-shadow", el)];       // offset drop shadow, outside the slot
    box(sh[0], fw, 8, 8, fh); box(sh[1], 8, fh, fw, 8);
    var bars = [];
    [[0, 0, fw, T, true], [0, fh - T, fw, T, true], [0, 0, T, fh, false], [fw - T, 0, T, fh, false]].forEach(function (b, k) {
      var bar = mk("ec-bar", el); box(bar, b[0], b[1], b[2], b[3]);
      bar.style.backgroundImage = wood(b[4], 300 + idx * 10 + k);
      bars.push(bar);
    });
    // studs at the corners
    [[0, 0], [1, 0], [0, 1], [1, 1]].forEach(function (c) {
      var s = mk("ec-stud", el); box(s, c[0] ? fw - T / 2 - 4 : T / 2 - 4, c[1] ? fh - T / 2 - 4 : T / 2 - 4, 8, 8);
    });
    var ms = mk("ec-moss", el);
    var mwpx = Math.round(fw / 4);
    box(ms, -2, -5, fw + 4, 20);                                // 5 texture rows x 4 px; drips stay within the top bar
    ms.style.backgroundImage = moss(mwpx, 500 + idx);
    var vine = null;
    if (vineSrc) {
      vine = mk("ec-vine", el);
      var vh = Math.min(d.vertical ? 74 : 92, vineN[1] * 0.9), vw = vh * vineN[0] / vineN[1];
      var right = d.vertical ? (idx === 2) : (idx === 2);
      box(vine, right ? fw - vw * 0.62 : -vw * 0.38, -vh * 0.3, vw, vh);
      put(vine, vineSrc);
      if (right) gsap.set(vine, { scaleX: -1 });
    }
    var txt = String(f[2] == null ? "" : f[2]).toUpperCase().trim(), lab = null;
    if (txt) {
      lab = mk("ec-label f-display", el);
      lab.textContent = txt;
      var fs = L.labSize;
      lab.style.fontSize = fs + "px";
      lab.style.padding = Math.round(fs * 0.32) + "px " + Math.round(fs * 0.5) + "px " + Math.round(fs * 0.12) + "px";
      var lx = (vine && !(idx === 2)) ? T + 30 : T + 4;
      lab.style.left = lx + "px"; lab.style.bottom = (fh + 6) + "px";
      [[0], [1]].forEach(function (c) {
        var s = mk("ec-stud", lab); s.style.top = "3px"; s.style[c[0] ? "right" : "left"] = "3px";
        s.style.width = s.style.height = "5px";
      });
    }
    frames.push({ el: el, bars: bars, moss: ms, vine: vine, lab: lab, idx: idx });
  });

  /* ---- logo (or fallback title) */
  var logo = document.getElementById("ec-logo"), title = document.getElementById("ec-title");
  if (logoSrc) {
    var lh = Math.min(L.logo[2], logoN[1] * 0.9), lw = lh * logoN[0] / logoN[1];
    if (lw > W * 0.8) { lw = W * 0.8; lh = lw * logoN[1] / logoN[0]; }
    box(logo, L.logo[0] - lw / 2, L.logo[1], lw, lh);
    put(document.getElementById("ec-logo-in"), logoSrc);
    title.style.display = "none";
  } else {
    var name = String(v.channel_name || "").toUpperCase();
    var ts = Math.floor(Math.min(L.logo[2] * 0.7, W * 0.8 / (Math.max(1, name.length) * 0.56)));
    title.textContent = name; title.style.fontSize = ts + "px";
    box(title, 0, L.logo[1] + (L.logo[2] - ts) / 2, W, ts);
    logo.style.display = "none";
  }

  /* ---- subscribe circle (empty centre) + label */
  var sub = document.getElementById("ec-sub"), R = L.sub[2];
  box(sub, L.sub[0] - R / 2, L.sub[1] - R / 2, R, R);
  var sl = document.getElementById("ec-sublabel"), slTxt = String(v.sub_label == null ? "" : v.sub_label).toUpperCase().trim();
  var slSize = d.vertical ? 17 : 22;
  sl.textContent = slTxt; sl.style.fontSize = slSize + "px";
  if (L.subLab === "right") { sl.style.left = (L.sub[0] + R / 2 + 26) + "px"; sl.style.top = (L.sub[1] - slSize / 2) + "px"; }
  else { box(sl, L.sub[0] - 80, L.sub[1] + R / 2 + 22, 160, slSize); sl.style.textAlign = "center"; }
  if (!slTxt) sl.style.display = "none";

  /* ---- mascot */
  var mascot = document.getElementById("ec-mascot");
  var mh = Math.min(L.mascot[2], mN[1] * 0.9), mw = mh * mN[0] / mN[1];
  if (d.vertical && mw > 150) { mw = 150; mh = mw * mN[1] / mN[0]; }
  box(mascot, L.mascot[0] - mw / 2, L.mascot[1] - mh, mw, mh);
  put(document.getElementById("ec-mascot-in"), mSrc);

  /* ---- floating pixel leaves / blocks in the empty spots */
  var deco = document.getElementById("ec-deco"), decos = [];
  var spots = d.vertical ? [[44, 128, 18], [492, 140, 22], [402, 214, 14], [500, 700, 16]]
                         : [[60, 470, 22], [880, 440, 26], [230, 505, 16], [760, 90, 18], [190, 70, 16]];
  var leafRows = ["..aa", ".abb", "abba", "bba."], leafPal = { a: C.leaf, b: C.lime };
  spots.forEach(function (s, i) {
    var e = mk("ec-leaf", deco);
    box(e, s[0], s[1], s[2], s[2]);
    e.innerHTML = i % 2 ? MC.pixelSVG(leafRows, leafPal, s[2] / 4)
                        : MC.pixelSVG(["aaaa", "abba", "bccb", "cccc"], { a: C.lime, b: MC.mix(C.lime, C.leaf, 0.5), c: "#9a5a2c" }, s[2] / 4);
    decos.push(e);
  });

  /* ---- timeline */
  var tl = gsap.timeline({ paused: true });
  tl.set("#ec-all", { opacity: 1 }, 0);
  tl.fromTo("#ec-scrim", { opacity: 0 }, { opacity: scrim, duration: 0.4, ease: "power1.out" }, 0);
  var head = logoSrc ? "#ec-logo-in" : "#ec-title";
  tl.fromTo(head, { y: -140, scale: 0.6, rotation: -6, opacity: 0 }, { y: 0, scale: 1, rotation: 0, opacity: 1, duration: 0.55, ease: "bounce.out" }, 0.1);
  frames.forEach(function (f, k) {
    var t0 = 0.4 + k * 0.14;
    gsap.set(f.el, { transformOrigin: "50% 50%" });
    tl.fromTo(f.el, { scale: 0.3, rotation: k ? 7 : -7, opacity: 0 }, { scale: 1, rotation: 0, opacity: 1, duration: 0.42, ease: "back.out(1.8)" }, t0);
    gsap.set(f.moss, { transformOrigin: "50% 0%" });
    tl.fromTo(f.moss, { scaleY: 0 }, { scaleY: 1, duration: 0.3, ease: "back.out(2.5)" }, t0 + 0.3);
    if (f.vine) {
      gsap.set(f.vine, { transformOrigin: "50% 20%" });
      tl.fromTo(f.vine, { scale: 0, rotation: -40 }, { scale: 1, rotation: 0, duration: 0.4, ease: "back.out(2.4)" }, t0 + 0.36);
      if (f.idx === 2) tl.set(f.vine, { scaleX: -1 }, t0 + 0.76);
    }
    if (f.lab) tl.fromTo(f.lab, { x: -40, opacity: 0, rotation: -8 }, { x: 0, opacity: 1, rotation: -2, duration: 0.32, ease: "back.out(2.2)" }, t0 + 0.28);
  });
  tl.fromTo(sub, { scale: 0, rotation: -200 }, { scale: 1, rotation: 0, duration: 0.5, ease: "back.out(2)" }, 0.8);
  if (slTxt) tl.fromTo(sl, { opacity: 0, x: L.subLab === "right" ? -24 : 0, y: L.subLab === "right" ? 0 : -12 }, { opacity: 1, x: 0, y: 0, duration: 0.28, ease: "power3.out" }, 1.05);
  tl.fromTo(decos, { scale: 0, rotation: 0 }, { scale: 1, rotation: 0, duration: 0.3, ease: "back.out(3)", stagger: 0.07 }, 1.0);

  // Crodie jumps in, then waves (rotation about the feet) with a little hop every cycle
  var mIn = document.getElementById("ec-mascot-in");
  gsap.set(mIn, { transformOrigin: "50% 95%" });
  var OUT = D - 0.34, END = D - 0.04;
  if (mSrc) {
    tl.fromTo(mIn, { y: mh * 1.3, rotation: 0, opacity: 0 }, { y: -mh * 0.12, opacity: 1, duration: 0.28, ease: "power2.out" }, 0.95);
    tl.to(mIn, { y: 0, duration: 0.22, ease: "bounce.out" }, 1.23);
    var wStart = 1.5, cyc = 0.9, n = Math.max(1, Math.floor((OUT - wStart) / cyc));
    var ks = [];
    for (var i = 0; i < n; i++) {
      ks.push({ rotation: 7, y: -mh * 0.06, duration: cyc * 0.25, ease: "sine.out" });
      ks.push({ rotation: -5, y: 0, duration: cyc * 0.25, ease: "sine.in" });
      ks.push({ rotation: 6, duration: cyc * 0.25, ease: "sine.inOut" });
      ks.push({ rotation: 0, duration: cyc * 0.25, ease: "sine.inOut" });
    }
    tl.to(mIn, { keyframes: ks }, wStart);
  }
  // idle: logo bob, ring pulse, decor drift (finite)
  var idle0 = 1.6, ic = 1.6, reps = Math.max(1, Math.floor((OUT - idle0) / ic));
  tl.fromTo(head, { y: 0 }, { y: -5, duration: ic / 2, ease: "sine.inOut", yoyo: true, repeat: reps * 2 - 1, immediateRender: false }, idle0);
  tl.fromTo(sub, { scale: 1 }, { scale: 1.06, duration: ic / 2, ease: "sine.inOut", yoyo: true, repeat: reps * 2 - 1, immediateRender: false }, idle0);
  decos.forEach(function (b, i) {
    tl.fromTo(b, { y: 0, rotation: 0 }, { y: -8, rotation: i % 2 ? 10 : -10, duration: ic / 2, ease: "sine.inOut", yoyo: true, repeat: reps * 2 - 1, immediateRender: false }, idle0 + i * 0.1);
  });
  // fade out so the last frame is clear
  tl.to("#ec-all", { opacity: 0, duration: END - OUT, ease: "power1.in" }, OUT);
  tl.set("#ec-all", { opacity: 0 }, END);
  return tl;
});

