MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h, D = d.duration;
  var kind = String(v.kind || "thought").trim().toLowerCase() === "speech" ? "speech" : "thought";
  var POS = ["bottom-left", "bottom-right", "top-left", "top-right"];
  var pos = String(v.position || "bottom-left").trim().toLowerCase().replace(/[\s_]+/g, "-");
  if (POS.indexOf(pos) < 0) pos = "bottom-left";
  var left = /left/.test(pos), bottom = /bottom/.test(pos);
  var text = String(v.text == null ? "" : v.text).trim() || "...";

  function uri(x, what) {
    var s = String(x == null ? "" : x).trim();
    if (s && !/^(data:|https?:|blob:)/i.test(s)) { console.warn("crodie_thought: " + what + " path did not resolve; skipped"); return ""; }
    return s;
  }
  function imgSize(u) {
    var m = /^data:[^;,]*;base64,(.*)$/i.exec(u || "");
    if (!m) return null;
    var h; try { h = atob(m[1].slice(0, 64)); } catch (e) { return null; }
    var b = function (i) { return h.charCodeAt(i) & 255; };
    if (h.slice(1, 4) === "PNG") return [(b(16) << 24 | b(17) << 16 | b(18) << 8 | b(19)) >>> 0, (b(20) << 24 | b(21) << 16 | b(22) << 8 | b(23)) >>> 0];
    if (h.slice(0, 3) === "GIF") return [b(6) | b(7) << 8, b(8) | b(9) << 8];
    if (h.slice(0, 4) === "RIFF" && h.slice(12, 16) === "VP8X") return [(b(24) | b(25) << 8 | b(26) << 16) + 1, (b(27) | b(28) << 8 | b(29) << 16) + 1];
    return null;
  }
  function box(el, x, y, w, h) {
    el.style.left = x.toFixed(1) + "px"; el.style.top = y.toFixed(1) + "px";
    el.style.width = w.toFixed(1) + "px"; el.style.height = h.toFixed(1) + "px";
  }
  function mk(cls, parent) {
    var e = document.createElement("div"); e.className = cls;
    e.setAttribute("data-layout-allow-overlap", ""); e.setAttribute("data-layout-allow-overflow", "");
    parent.appendChild(e); return e;
  }
  var hSrc = uri(v.head, "head"), hN = imgSize(hSrc) || [165, 208];

  /* ---- safe area + head */
  var safeTop = d.vertical ? H * 0.11 : H * 0.05, safeBot = d.vertical ? H * 0.725 : H * 0.95, mX = W * 0.04;
  var hh = hSrc ? Math.min(d.vertical ? 130 : 140, hN[1] * 0.9) : 0, hw = hSrc ? hh * hN[0] / hN[1] : 0;
  if (hw > hh * 1.3) { hw = hh * 1.3; hh = hw * hN[1] / hN[0]; }
  var hx = left ? mX : W - mX - hw, hy = bottom ? safeBot - hh : safeTop;
  var head = document.getElementById("ct2-head");
  box(head, hx, hy, hw, hh);
  if (hSrc) {
    var img = document.createElement("img"); img.src = hSrc; img.alt = "";
    img.setAttribute("data-layout-allow-overflow", "");
    document.getElementById("ct2-head-in").appendChild(img);
  }

  /* ---- text fit -> bubble size */
  var maxW = d.vertical ? 300 : 330;
  var fit = MC.fit(text.toUpperCase() === text ? text : text, { maxWidth: maxW, maxSize: d.vertical ? 30 : 30, minSize: 13, maxLines: 3, k: 0.6, lineHeight: 1.15 });
  var fs = fit.size, longest = 0;
  fit.lines.forEach(function (l) { longest = Math.max(longest, l.length); });
  var padX = Math.round(fs * 0.9), padY = Math.round(fs * 0.65);
  var bw = Math.max(fs * 4, Math.round(longest * fs * 0.6 + padX * 2)), bh = Math.round(fit.lines.length * fs * 1.15 + padY * 2);
  var gapY = kind === "thought" ? 54 : 40;
  var bx = left ? hx + hw * 0.62 : hx + hw * 0.38 - bw;
  if (!hSrc) bx = left ? mX : W - mX - bw;
  bx = Math.max(mX * 0.5, Math.min(W - mX * 0.5 - bw, bx));
  var by = bottom ? hy + hh * 0.05 - gapY - bh : hy + hh * 0.95 + gapY;
  if (!hSrc) by = bottom ? safeBot - bh - gapY : safeTop + gapY;
  by = Math.max(safeTop, Math.min(safeBot - bh, by));

  /* ---- bubble layers (all relative to the bubble box): shadow, black, paper, text */
  var bub = document.getElementById("ct2-bubble");
  box(bub, bx, by, bw, bh);
  var B = 3;                                         // border px
  function stepPoly(w, h, s, n, ox, oy) {
    var tlc = [];
    for (var i = 0; i < n; i++) { tlc.push([i * s, (n - i) * s]); tlc.push([(i + 1) * s, (n - i) * s]); }
    tlc.push([n * s, 0]);
    var pts = [], k;
    for (k = 0; k < tlc.length; k++) pts.push([tlc[k][0], tlc[k][1]]);
    for (k = tlc.length - 1; k >= 0; k--) pts.push([w - tlc[k][0], tlc[k][1]]);
    for (k = 0; k < tlc.length; k++) pts.push([w - tlc[k][0], h - tlc[k][1]]);
    for (k = tlc.length - 1; k >= 0; k--) pts.push([tlc[k][0], h - tlc[k][1]]);
    return "polygon(" + pts.map(function (p) { return (p[0] + (ox || 0)).toFixed(1) + "px " + (p[1] + (oy || 0)).toFixed(1) + "px"; }).join(",") + ")";
  }
  var step = kind === "thought" ? 7 : 5, nSteps = kind === "thought" ? 3 : 2;
  // tail: blocks from the bubble edge (A) toward the head (T)
  var Ax = left ? bw * 0.22 : bw * 0.78, Ay = bottom ? bh : 0;
  var Tx = hSrc ? (hx + hw * (left ? 0.62 : 0.38)) - bx : Ax + (left ? -30 : 30);
