  if (hSrc) tl.to(hIn, { y: bottom ? hh : -hh, scale: 0.5, opacity: 0, duration: 0.2, ease: "back.in(1.8)" }, OUT + 0.04);
  tl.set("#ct2-all", { opacity: 0 }, END);
  return tl;
});

