{
  "description": "2.2s loot reveal: a Crodie emote pops up and an item card spins up out of its hands with a rarity glow (common white / rare blue / epic purple / legendary orange), rotating light rays and sparkles; the item name slams in under it with a rarity tag and an xN count badge.",
  "kind": "overlay",
  "duration": 2.2,
  "orientations": ["landscape", "vertical"],
  "vars": {
    "item":   {"type": "string", "label": "Item name", "default": "DIAMONDS"},
    "count":  {"type": "string", "label": "Count badge text: a number (3 -> x3) or literal text; empty / 0 / 1 = no badge", "default": "3"},
    "rarity": {"type": "string", "label": "common (white) | rare (blue) | epic (purple) | legendary (orange)", "default": "rare"},
    "icon":   {"type": "string", "label": "Item icon (local path / data URI). Empty = built-in pixel diamond", "default": ""},
    "emote":  {"type": "string", "label": "Crodie emote holding it up (local path): brand/crodie/emotes/heart_eyes.png, diamond_hug.png, star_grin.png ... Empty = none", "default": "brand/crodie/emotes/heart_eyes.png"},
    "tag":    {"type": "string", "label": "Small tag above the card; 'auto' = the rarity name, empty = none", "default": "auto"},
    "opaque": {"type": "boolean", "label": "Opaque ink background", "default": false}
  }
}

input.content:
#cl-all, #cl-sparks { position: absolute; inset: 0; }
#cl-rays, #cl-glow, #cl-cardpos, #cl-name, #cl-emote, #cl-flash { position: absolute; }
#cl-emote-in { position: absolute; inset: 0; }
#cl-emote img {
  display: block; width: 100%; height: 100%; object-fit: contain;
  filter: drop-shadow(0 3px 0 rgba(0,0,0,0.35)) drop-shadow(0 6px 8px rgba(0,0,0,0.4));
}
#cl-rays { border-radius: 50%; opacity: 0;
  background: repeating-conic-gradient(from 0deg, var(--rc) 0deg 10deg, transparent 10deg 30deg);
  -webkit-mask-image: radial-gradient(circle, #000 0 22%, rgba(0,0,0,0) 70%);
  mask-image: radial-gradient(circle, #000 0 22%, rgba(0,0,0,0) 70%); }
#cl-glow { border-radius: 50%; opacity: 0; background: radial-gradient(circle, var(--rc) 0 25%, transparent 68%); }
#cl-card { position: absolute; inset: 0;
  background: linear-gradient(180deg, #3a4527 0%, var(--olive) 55%, #232b16 100%);
  border: 6px solid var(--rc); outline: 3px solid #000;
  box-shadow: inset 4px 4px 0 rgba(255,255,255,0.18), inset -4px -4px 0 rgba(0,0,0,0.4), 0 0 0 3px #000, 7px 9px 0 3px rgba(0,0,0,0.45); }
#cl-icon { position: absolute; }
#cl-icon img, #cl-icon svg { display: block; width: 100%; height: 100%; object-fit: contain; }
#cl-icon img { filter: drop-shadow(0 3px 0 rgba(0,0,0,0.4)); }
#cl-count { position: absolute; color: var(--paper); line-height: 1; white-space: nowrap; }
#cl-tag { position: absolute; left: 50%; line-height: 1; white-space: nowrap; color: var(--ink);
  background: var(--rc); border: 3px solid #000; box-shadow: 3px 3px 0 #000; }
#cl-name { color: var(--rc); line-height: 1; white-space: nowrap; text-align: center; }
#cl-flash { border-radius: 50%; opacity: 0;
  background: radial-gradient(circle, #fff 0 35%, rgba(255,255,255,0.6) 52%, rgba(255,255,255,0) 70%); }
.cl-spark { position: absolute; opacity: 0; background: #fff;
  clip-path: polygon(50% 0, 62% 38%, 100% 50%, 62% 62%, 50% 100%, 38% 62%, 0 50%, 38% 38%); }

