  box(flash, ccx - R * 0.9, ccy - R * 0.9, R * 1.8, R * 1.8);

  var eh = Math.min(vert ? 150 : 140, eN[1] * 0.9), ew = eh * eN[0] / eN[1];
  var ex = ccx - cw / 2 - ew * 0.78, ey = ccy + chh / 2 - eh * 0.62;
  ex = Math.max(W * 0.03, ex);
  var emote = document.getElementById("cl-emote");
  box(emote, ex, ey, ew, eh);
  put(document.getElementById("cl-emote-in"), eSrc);

  var sparks = document.getElementById("cl-sparks"), sp = [];
  var nS = legendary ? 12 : 8;
  for (var i = 0; i < nS; i++) {
    var s = mk("cl-spark", sparks), ss = 10 + rnd() * 14;
    var a = (i / nS) * Math.PI * 2 + rnd() * 0.5, rr = cw * (0.75 + rnd() * 0.45);
    box(s, ccx + Math.cos(a) * rr - ss / 2, ccy + Math.sin(a) * rr * 0.9 - ss / 2, ss, ss);
    s.style.background = i % 3 === 0 ? rc : "#ffffff";
    sp.push(s);
  }

  /* ---- timeline */
  var tl = gsap.timeline({ paused: true });
  var OUT = D - 0.27, END = D - 0.04, REV = 0.62;
  tl.set("#cl-all", { opacity: 1 }, 0);
  var eIn = document.getElementById("cl-emote-in");
  gsap.set(eIn, { transformOrigin: "50% 100%" });
  if (eSrc) {
    tl.fromTo(eIn, { y: eh * 0.6, scale: 0.3, rotation: -15, opacity: 0 }, { y: 0, scale: 1, rotation: 0, opacity: 1, duration: 0.28, ease: "back.out(2.4)" }, 0);
    tl.to(eIn, { keyframes: [{ scaleY: 0.88, scaleX: 1.08, duration: 0.07 }, { scaleY: 1.08, scaleX: 0.95, y: -eh * 0.12, duration: 0.12, ease: "power2.out" },
                             { scaleY: 1, scaleX: 1, y: 0, duration: 0.14, ease: "bounce.out" }] }, REV - 0.06);
    var hopN = Math.max(1, Math.floor((OUT - REV - 0.4) / 0.32));
    tl.fromTo(eIn, { y: 0, rotation: 0 }, { y: -eh * 0.05, rotation: 4, duration: (OUT - REV - 0.4) / (2 * hopN), ease: "sine.inOut", yoyo: true, repeat: 2 * hopN - 1, immediateRender: false }, REV + 0.34);
  }
  var card = document.getElementById("cl-card");
  gsap.set(cardpos, { transformPerspective: 700, transformOrigin: "50% 50%" });
  var fromX = (ex + ew * 0.7) - ccx, fromY = (ey + eh * 0.4) - ccy;
  tl.fromTo(cardpos, { x: fromX, y: fromY, scale: 0.15, rotationY: 720 + 180, rotation: -20, opacity: 0 },
    { x: 0, y: 0, scale: 1, rotationY: 0, rotation: 0, opacity: 1, duration: REV - 0.12, ease: "power3.out" }, 0.12);
  tl.to(cardpos, { keyframes: [{ scale: 1.12, duration: 0.07, ease: "power2.out" }, { scale: 1, duration: 0.16, ease: "back.out(3)" }] }, REV);
  tl.fromTo(flash, { scale: 0.3, opacity: 0 }, { keyframes: [{ scale: 0.9, opacity: 1, duration: 0.06 }, { scale: 1.3, opacity: 0, duration: 0.24, ease: "power1.in" }] }, REV - 0.02);
  tl.fromTo(glow, { scale: 0.4, opacity: 0 }, { scale: 1, opacity: legendary ? 0.85 : 0.6, duration: 0.25, ease: "power2.out" }, REV);
  tl.fromTo(rays, { scale: 0.5, opacity: 0, rotation: 0 }, { scale: 1, opacity: legendary ? 0.75 : 0.5, rotation: 20, duration: 0.3, ease: "power2.out" }, REV);
  tl.to(rays, { rotation: 20 + (OUT - REV - 0.3) * 40, duration: OUT - REV - 0.3, ease: "none" }, REV + 0.3);
  var gN = Math.max(1, Math.floor((OUT - REV - 0.25) / 0.5));
  tl.fromTo(glow, { scale: 1 }, { scale: 1.1, duration: (OUT - REV - 0.25) / (2 * gN), ease: "sine.inOut", yoyo: true, repeat: 2 * gN - 1, immediateRender: false }, REV + 0.25);
  // card float
  var fN = Math.max(1, Math.floor((OUT - REV - 0.3) / 0.6));
  tl.fromTo(card, { y: 0 }, { y: -5, duration: (OUT - REV - 0.3) / (2 * fN), ease: "sine.inOut", yoyo: true, repeat: 2 * fN - 1, immediateRender: false }, REV + 0.3);
  if (tag) tl.fromTo(tg, { scale: 0, y: 10 }, { scale: 1, y: 0, duration: 0.22, ease: "back.out(3)" }, REV + 0.06);
  if (item) tl.fromTo(name, { scale: 1.8, opacity: 0, y: -10 }, { scale: 1, opacity: 1, y: 0, duration: 0.2, ease: "power3.in" }, REV + 0.08);
  if (item) tl.to(name, { keyframes: [{ scale: 1.06, duration: 0.06 }, { scale: 1, duration: 0.12 }] }, REV + 0.28);
  if (cnt) tl.fromTo(count, { scale: 0, rotation: -40 }, { scale: 1, rotation: -8, duration: 0.28, ease: "back.out(3)" }, REV + 0.2);
  sp.forEach(function (s, k) {
    var t0 = REV + 0.05 + (k / sp.length) * 0.5;
    var reps = Math.max(1, Math.floor((OUT - t0) / 0.5));
    tl.fromTo(s, { scale: 0, opacity: 0, rotation: 0 }, { keyframes: [
      { scale: 1.2, opacity: 1, rotation: 45, duration: 0.16, ease: "back.out(3)" },
      { scale: 0, opacity: 0, rotation: 90, duration: 0.26, ease: "power1.in" },
      { scale: 0, duration: 0.08 }], repeat: reps - 1 }, t0);
  });
  // exit
  tl.to([rays, glow], { opacity: 0, scale: 0.6, duration: 0.18, ease: "power1.in" }, OUT);
  tl.to(cardpos, { scale: 0, rotationY: -180, duration: 0.2, ease: "back.in(1.8)" }, OUT + 0.02);
  if (item) tl.to(name, { scale: 0, opacity: 0, duration: 0.16, ease: "back.in(2)" }, OUT);
  if (eSrc) tl.to(eIn, { y: eh * 0.5, scale: 0, duration: 0.2, ease: "back.in(2)" }, OUT + 0.03);
  tl.set("#cl-all", { opacity: 0 }, END);
  return tl;
});

